    # Convenience functions for common use cases
    def create_mini_brain(neuron_count=1000, simulate_steps=100):
        """
        Create a mini brain with default settings for quick testing.
        
        Args:
            neuron_count: Number of neurons (default: 1000)
            simulate_steps: Number of steps to simulate (default: 100)
            
        Returns:
            tuple: (brain, final_firing_rate)
        """
        config = createDefaultConfig()
        config.set("neuron_count", neuron_count)
        
        brain = createBrain(config)
        brain.initialize()
        
        for i in range(simulate_steps):
            brain.step(i)
        
        return brain, brain.getAverageFiringRate()
    
    def create_agent_simulation(width=20, height=20, vision_width=8, vision_height=8, 
                               steps=500, enable_learning=True):
        """
        Create a complete agent simulation with world and learning enabled.
        
        Args:
            width: World width
            height: World height
            vision_width: Vision sensor width
            vision_height: Vision sensor height
            steps: Number of simulation steps
            enable_learning: Enable learning features (reward, curiosity, development)
            
        Returns:
            tuple: (brain, agent, world, final_stats)
        """
        config = createDefaultConfig()
        brain = createBrain(config)
        brain.initialize()
        
        agent = createAgentBrain(brain)
        
        world = createSimpleWorld()
        world.configure(width, height, vision_width, vision_height)
        world.reset()
        
        agent.initialize(world)
        
        if enable_learning:
            agent.enableRewardModulation(True)
            agent.enableCuriosity(True)
            agent.enableDevelopment(True)
        
        # Run simulation
        for step in range(steps):
            world.update(0.1)
            agent.processSensoryInput(world.getSensoryPercept())
            brain.step(step)
            action = agent.decodeMotorCommand()
            world.applyMotorCommand(action, world.getSimulationTime())
        
        # Collect statistics
        stats = {
            'firing_rate': brain.getAverageFiringRate(),
            'curiosity': agent.getCuriosityLevel(),
            'novelty': agent.getNoveltyLevel(),
            'development_stage': brain.getDevelopmentalStage(),
            'total_spikes': brain.getTotalSpikeCount(),
        }
        
        return brain, agent, world, stats
    
    def benchmark(neuron_counts=[100, 1000, 5000], steps=1000):
        """
        Benchmark NLM performance with different neuron counts.
        
        Args:
            neuron_counts: List of neuron counts to test
            steps: Number of simulation steps per test
            
        Returns:
            list: Benchmark results for each configuration
        """
        results = []
        
        for neuron_count in neuron_counts:
            config = createDefaultConfig()
            config.set("neuron_count", neuron_count)
            
            brain = createBrain(config)
            brain.initialize()
            
            import time
            start_time = time.time()
            
            for step in range(steps):
                brain.step(step)
            
            end_time = time.time()
            wall_time = end_time - start_time
            
            result = {
                'neuron_count': neuron_count,
                'steps': steps,
                'wall_time_seconds': wall_time,
                'steps_per_second': steps / wall_time if wall_time > 0 else 0,
                'avg_firing_rate': brain.getAverageFiringRate(),
                'total_spikes': brain.getTotalSpikeCount(),
                'real_time_factor': wall_time / (steps * 0.001),  # Assuming 1ms timestep
            }
            
            results.append(result)
            print(f"Benchmark ({neuron_count} neurons, {steps} steps): "
                  f"{result['steps_per_second']:.0f} steps/sec, "
                  f"firing rate: {result['avg_firing_rate']:.2f}")
        
        return results
    
